5: /// Read-only, main-actor adapter for an already selected app-owned container.
6: /// It never selects a path, creates a container, or saves/resets the caller.
7: @MainActor
8: final class InventoryReadAdapter {
9:     enum Failure: Error, Equatable {
10:         case pendingEdits, invalidQuery, notFound, invalidCursor, staleCursor
11:         case rowLimit, fieldLimit, projectionLimit, responseLimit, invalidData, unsupportedSchema
12:     }
13:     enum Kind: String, Codable { case items, locations, tags }
14:     enum ArchiveScope: String, Codable { case active, archived, all }
15:     enum Plan: String, Codable {
16:         case keep = "Keep", throwAway = "Throw Away", sell = "Sell", charity = "Charity", move = "Move", fix = "Fix"
17:     }
18:     struct PathEntry: Codable { let id: UUID; let name: String }
19:     struct ItemValue: Codable {
20:         let id: UUID; let name: String; let dateAdded: Date; let locationID: UUID?
21:         let tagIDs: [UUID]; let plan: Plan?; let moveDestination: String?
22:         let isBook: Bool; let bookTitle: String?; let bookAuthor: String?; let displayName: String
23:         let isArchived: Bool; let archivedDate: Date?; let archivedPlan: Plan?
24:     }
25:     struct LocationValue: Codable {
26:         let id: UUID; let name: String; let dateAdded: Date; let parentID: UUID?
27:         let childIDs: [UUID]; let itemIDs: [UUID]; let isReviewed: Bool; let lastReviewedDate: Date?
28:         let path: [PathEntry]
29:     }
30:     struct TagValue: Codable {
31:         let id: UUID; let name: String; let color: String; let dateAdded: Date?; let itemIDs: [UUID]
32:     }
33:     struct HistoryValue: Codable {
34:         let id: UUID; let date: Date; let action: ReviewAction; let isAutomatic: Bool; let locationID: UUID?
35:     }
36:     struct ExclusionValue: Codable {
37:         let id: UUID; let itemID1: UUID; let itemID2: UUID; let dateCreated: Date
38:     }
39:     enum Record: Codable {
40:         case item(ItemValue), location(LocationValue), tag(TagValue)
41:         var id: UUID {
42:             switch self { case .item(let v): return v.id; case .location(let v): return v.id; case .tag(let v): return v.id }
43:         }
44:     }
45:     struct Counts: Codable {
46:         let items: Int; let locations: Int; let tags: Int; let histories: Int; let exclusions: Int
47:         let activeItems: Int; let archivedItems: Int
48:     }
49:     struct Status: Codable {
50:         let scope: UUID; let revision: String; let counts: Counts
51:         let complete: Bool; let transactionalSnapshot: Bool
52:     }
53:     struct Page: Codable {
54:         let scope: UUID; let revision: String; let records: [Record]; let total: Int
55:         let complete: Bool; let next: String?
56:     }
57:     struct Detail: Codable {
58:         let scope: UUID; let revision: String; let record: Record
59:         let histories: [HistoryValue]; let exclusions: [ExclusionValue]
60:     }
61:     private struct Projection: Codable {
62:         let items: [ItemValue]; let locations: [LocationValue]; let tags: [TagValue]
63:         let histories: [HistoryValue]; let exclusions: [ExclusionValue]
64:         func records(_ kind: Kind, _ archive: ArchiveScope) -> [Record] {
65:             switch kind {
66:             case .items: return items.filter { archive == .all || $0.isArchived == (archive == .archived) }.map(Record.item)
67:             case .locations: return locations.map(Record.location)
68:             case .tags: return tags.map(Record.tag)
69:             }
70:         }
71:     }
72:     private struct Cursor: Codable {
73:         let version: Int; let scope: UUID; let revision: String; let kind: Kind
74:         let archive: ArchiveScope; let size: Int; let last: UUID
75:     }
76:     private let context: ModelContext
77:     private let scope = UUID()
78:     private let cursorKey = SymmetricKey(size: .bits256)
79:     static let maximumRows = 5000
80:     static let maximumFieldBytes = 16 * 1024
81:     static let maximumProjectionBytes = 4 * 1024 * 1024
82:     static let maximumResponseBytes = 1024 * 1024
83: 
84:     init(context: ModelContext) { self.context = context }
85: 
86:     private func encoded<T: Encodable>(_ value: T) throws -> Data {
87:         let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
88:         encoder.dateEncodingStrategy = .secondsSince1970
89:         return try encoder.encode(value)
90:     }
91:     private func bounded<T: Encodable>(_ value: T) throws -> T {
92:         guard try encoded(value).count <= Self.maximumResponseBytes else { throw Failure.responseLimit }
93:         return value
94:     }
95:     private func rows<T: PersistentModel>(_ type: T.Type, _ reader: ModelContext) throws -> [T] {
96:         var descriptor = FetchDescriptor<T>(); descriptor.fetchLimit = Self.maximumRows + 1
97:         let values = try reader.fetch(descriptor)
98:         guard values.count <= Self.maximumRows else { throw Failure.rowLimit }
99:         return values
100:     }
101:     private func text(_ values: String?...) throws {
102:         guard values.allSatisfy({ ($0?.utf8.count ?? 0) <= Self.maximumFieldBytes }) else { throw Failure.fieldLimit }
103:     }
104:     private func dates(_ values: Date?...) throws {
105:         guard values.allSatisfy({ $0?.timeIntervalSince1970.isFinite ?? true }) else { throw Failure.invalidData }
106:     }
107:     private func ids(_ values: [UUID]) throws -> [UUID] {
108:         guard values.count <= Self.maximumRows, Set(values).count == values.count else { throw Failure.invalidData }
109:         return values.sorted { $0.uuidString < $1.uuidString }
110:     }
111:     private func index<T>(_ values: [T], _ id: (T) -> UUID) throws -> [UUID: T] {
112:         var result: [UUID: T] = [:]
113:         for value in values { guard result.updateValue(value, forKey: id(value)) == nil else { throw Failure.invalidData } }
114:         return result
115:     }
116:     private func charge<T: Encodable>(_ value: T, _ used: inout Int) throws {
117:         used += try encoded(value).count
118:         guard used <= Self.maximumProjectionBytes else { throw Failure.projectionLimit }
119:     }
120:     private func projection() throws -> (Projection, String) {
121:         guard !context.hasChanges else { throw Failure.pendingEdits }
122:         let names = Set(context.container.schema.entities.map { $0.name.split(separator: ".").last.map(String.init) ?? $0.name })
123:         guard Set(["Location", "Item", "Tag", "ReviewHistory", "DuplicateExclusion"]).isSubset(of: names) else { throw Failure.unsupportedSchema }
124:         let reader = ModelContext(context.container); reader.autosaveEnabled = false
125:         // Independent fresh fetches are an observed projection, not a distributed snapshot.
126:         let locations = try rows(Location.self, reader), items = try rows(Item.self, reader), tags = try rows(Tag.self, reader)
127:         let histories = try rows(ReviewHistory.self, reader), exclusions = try rows(DuplicateExclusion.self, reader)
128:         let lm = try index(locations, { $0.id }), im = try index(items, { $0.id }), tm = try index(tags, { $0.id })
129:         _ = try index(histories, { $0.id }); _ = try index(exclusions, { $0.id })
130:         var lv: [LocationValue] = [], iv: [ItemValue] = [], tv: [TagValue] = []
131:         var hv: [HistoryValue] = [], ev: [ExclusionValue] = []
132:         var encodedBytes = 0
133:         for row in locations {
134:             try text(row.name); try dates(row.dateAdded, row.lastReviewedDate)
135:             var path: [PathEntry] = [], seen: Set<UUID> = [], current: Location? = row
136:             while let node = current {
137:                 guard lm[node.id] != nil, seen.insert(node.id).inserted, path.count < 15 else { throw Failure.invalidData }
138:                 try text(node.name); path.append(PathEntry(id: node.id, name: node.name)); current = node.parent
139:             }
140:             let children = try ids(row.children.map(\.id)), contained = try ids(row.items.map(\.id))
141:             guard children.allSatisfy({ lm[$0]?.parent?.id == row.id }), contained.allSatisfy({ im[$0]?.location?.id == row.id }) else { throw Failure.invalidData }
142:             if let parent = row.parent { guard lm[parent.id]?.children.contains(where: { $0.id == row.id }) == true else { throw Failure.invalidData } }
143:             lv.append(LocationValue(id: row.id, name: row.name, dateAdded: row.dateAdded, parentID: row.parent?.id, childIDs: children, itemIDs: contained, isReviewed: row.isReviewed, lastReviewedDate: row.lastReviewedDate, path: path.reversed()))
144:             try charge(lv.last!, &encodedBytes)
145:         }
146:         for row in items {
147:             try text(row.name, row.moveDestination, row.bookTitle, row.bookAuthor, row.displayName); try dates(row.dateAdded, row.archivedDate)
148:             if let location = row.location { guard lm[location.id]?.items.contains(where: { $0.id == row.id }) == true else { throw Failure.invalidData } }
149:             let tagIDs = try ids(row.tags.map(\.id))
150:             guard tagIDs.allSatisfy({ tm[$0] != nil }) else { throw Failure.invalidData }
151:             iv.append(ItemValue(id: row.id, name: row.name, dateAdded: row.dateAdded, locationID: row.location?.id, tagIDs: tagIDs, plan: row.plan.flatMap { Plan(rawValue: $0.rawValue) }, moveDestination: row.moveDestination, isBook: row.isBook, bookTitle: row.bookTitle, bookAuthor: row.bookAuthor, displayName: row.displayName, isArchived: row.isArchived, archivedDate: row.archivedDate, archivedPlan: row.archivedPlan.flatMap { Plan(rawValue: $0.rawValue) }))
152:             try charge(iv.last!, &encodedBytes)
153:         }
154:         for row in tags {
155:             try text(row.name, row.color); try dates(row.dateAdded)
156:             let itemIDs = try ids(row.items.map(\.id))
157:             guard itemIDs.allSatisfy({ im[$0] != nil }) else { throw Failure.invalidData }
158:             tv.append(TagValue(id: row.id, name: row.name, color: row.color, dateAdded: row.dateAdded, itemIDs: itemIDs))
159:             try charge(tv.last!, &encodedBytes)
160:         }
161:         for row in histories {
162:             try dates(row.date)
163:             if let location = row.location { guard lm[location.id] != nil else { throw Failure.invalidData } }
164:             hv.append(HistoryValue(id: row.id, date: row.date, action: row.action, isAutomatic: row.isAutomatic, locationID: row.location?.id))
165:             try charge(hv.last!, &encodedBytes)
166:         }
167:         for row in exclusions {
168:             try dates(row.dateCreated)
169:             guard im[row.itemID1] != nil, im[row.itemID2] != nil else { throw Failure.invalidData }
170:             ev.append(ExclusionValue(id: row.id, itemID1: row.itemID1, itemID2: row.itemID2, dateCreated: row.dateCreated))
171:             try charge(ev.last!, &encodedBytes)
172:         }
173:         let value = Projection(items: iv.sorted { $0.id.uuidString < $1.id.uuidString }, locations: lv.sorted { $0.id.uuidString < $1.id.uuidString }, tags: tv.sorted { $0.id.uuidString < $1.id.uuidString }, histories: hv.sorted { $0.id.uuidString < $1.id.uuidString }, exclusions: ev.sorted { $0.id.uuidString < $1.id.uuidString })
174:         let data = try encoded(value)
175:         guard data.count <= Self.maximumProjectionBytes else { throw Failure.projectionLimit }
176:         return (value, SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined())
177:     }
178:     private func token(_ cursor: Cursor) throws -> String {
179:         let data = try encoded(cursor)
180:         let signature = Data(HMAC<SHA256>.authenticationCode(for: data, using: cursorKey))
181:         return data.base64EncodedString() + "." + signature.base64EncodedString()
182:     }
183:     private func decode(_ raw: String) throws -> Cursor {
184:         guard raw.utf8.count <= 2048 else { throw Failure.invalidCursor }
185:         let parts = raw.split(separator: ".", omittingEmptySubsequences: false)
186:         guard parts.count == 2, let data = Data(base64Encoded: String(parts[0])), let signature = Data(base64Encoded: String(parts[1])), HMAC<SHA256>.isValidAuthenticationCode(signature, authenticating: data, using: cursorKey) else { throw Failure.invalidCursor }
187:         do { return try JSONDecoder().decode(Cursor.self, from: data) } catch { throw Failure.invalidCursor }
188:     }
189:     func status() throws -> Status {
190:         let (p, revision) = try projection(); let archived = p.items.filter(\.isArchived).count
191:         return try bounded(Status(scope: scope, revision: revision, counts: Counts(items: p.items.count, locations: p.locations.count, tags: p.tags.count, histories: p.histories.count, exclusions: p.exclusions.count, activeItems: p.items.count - archived, archivedItems: archived), complete: true, transactionalSnapshot: false))
192:     }
193:     func list(kind: Kind, archive: ArchiveScope, pageSize: Int, cursor: String? = nil) throws -> Page {
194:         guard (1...100).contains(pageSize), kind == .items || archive == .all else { throw Failure.invalidQuery }
195:         let decoded = try cursor.map(decode)
196:         if let c = decoded { guard c.version == 1, c.scope == scope, c.kind == kind, c.archive == archive, c.size == pageSize else { throw Failure.invalidCursor } }
197:         let (p, revision) = try projection(); let records = p.records(kind, archive)
198:         var start = 0
199:         if let c = decoded {
200:             guard c.revision == revision else { throw Failure.staleCursor }
201:             guard let previous = records.firstIndex(where: { $0.id == c.last }), previous + 1 < records.count else { throw Failure.invalidCursor }
202:             start = previous + 1
203:         }
204:         let end = min(start + pageSize, records.count), batch = Array(records[start..<end])
205:         let next = end < records.count ? try token(Cursor(version: 1, scope: scope, revision: revision, kind: kind, archive: archive, size: pageSize, last: batch.last!.id)) : nil
206:         return try bounded(Page(scope: scope, revision: revision, records: batch, total: records.count, complete: next == nil, next: next))
207:     }
208:     func show(kind: Kind, id: UUID) throws -> Detail {
209:         let (p, revision) = try projection()
210:         guard let record = p.records(kind, .all).first(where: { $0.id == id }) else { throw Failure.notFound }
211:         let relatedItems: Set<UUID>
212:         if case .location(let location) = record { relatedItems = Set(location.itemIDs) }
213:         else if case .item = record { relatedItems = [id] }
214:         else { relatedItems = [] }
215:         return try bounded(Detail(scope: scope, revision: revision, record: record, histories: kind == .locations ? p.histories.filter { $0.locationID == id } : [], exclusions: p.exclusions.filter { relatedItems.contains($0.itemID1) || relatedItems.contains($0.itemID2) }))
216:     }
217: }


