7:     var name: String
8:     var dateAdded: Date
9: 
10:     // A room’s parent == nil
11:     var parent: Location?
12: 
13:     // Children containers
14:     @Relationship(deleteRule: .cascade, inverse: \Location.parent)
15:     var children: [Location] = []
16: 
17:     // Items stored here
18:     @Relationship(deleteRule: .cascade, inverse: \Item.location)
19:     var items: [Item] = []
20:     
21:     // Review tracking
22:     var isReviewed: Bool = false
23:     var lastReviewedDate: Date?
24:     
25:     // Review history
26:     @Relationship(deleteRule: .cascade, inverse: \ReviewHistory.location)
27:     var reviewHistory: [ReviewHistory] = []
28: 
29:     // MARK: - Convenience
30: 
31:     /// Depth of this node in the hierarchy (rooms are depth 1).
32:     var depth: Int { (parent?.depth ?? 0) + 1 }
33: 
34:     /// Distance to the deepest descendant (0 if no children).
35:     func deepestSubtreeDistance() -> Int {
36:         guard !children.isEmpty else { return 0 }
37:         return 1 + (children.map { $0.deepestSubtreeDistance() }.max() ?? 0)
38:     }
39: 
40:     /// IDs of self + all descendants (helps block illegal move targets).
41:     func collectIDs() -> Set<UUID> {
42:         children.reduce(into: Set([id])) { partial, child in
