1: import Foundation
2: import SwiftData
3: 
4: @Model
5: final class DuplicateExclusion {
6:     @Attribute(.unique) var id: UUID
7:     var itemID1: UUID   // Canonical ordering: smaller UUID string first
8:     var itemID2: UUID
9:     var dateCreated: Date
10: 
11:     init(itemID1: UUID, itemID2: UUID) {
12:         self.id = UUID()
13:         self.dateCreated = Date()
14: 
15:         // Canonical ordering: smaller UUID string goes first
16:         if itemID1.uuidString < itemID2.uuidString {
17:             self.itemID1 = itemID1
18:             self.itemID2 = itemID2
19:         } else {
20:             self.itemID1 = itemID2
21:             self.itemID2 = itemID1
22:         }
23:     }
24: 
25:     /// Check if this exclusion covers the given pair (order-independent).
26:     func covers(_ a: UUID, _ b: UUID) -> Bool {
27:         let canonA = a.uuidString < b.uuidString ? a : b
28:         let canonB = a.uuidString < b.uuidString ? b : a
29:         return itemID1 == canonA && itemID2 == canonB
30:     }
31: }


